import {startup} from './startup.js';startup.skip();
// Isolated fixture: no API, MCP or game requests. The banner identifies all synthetic data.
import {Research} from './research.js';import {Damage} from './damage.js';import {CombatAlert} from './combat-alert.js';
import {researchModel,researchSample} from './research-model.js';import {damageModel,combatStatus} from './combat-model.js';
import {FrameClock} from './frame-clock.js';import {Localization} from './i18n.js';import {PixiCrtOverlay} from './vfx/pixi-overlay.js';
const i18n=await Localization.load();i18n.apply();const clock=new FrameClock(30),tick=54000,scope={surface:'nauvis',force:'player'};
document.querySelector('#link-text').textContent='ПРОВЕРОЧНЫЕ ДАННЫЕ';document.querySelector('#link-state').dataset.state='ready';const o=document.createElement('option');o.textContent='Русский';document.querySelector('#language').append(o);document.querySelector('#vfx-status').textContent=i18n.text('vfx.on');
const names=['automation-science-pack','logistic-science-pack','military-science-pack','chemical-science-pack','production-science-pack','utility-science-pack','space-science-pack','metallurgic-science-pack','agricultural-science-pack','electromagnetic-science-pack','cryogenic-science-pack','promethium-science-pack'];
const current={force:'player',current:'mining-productivity-4',level:4,progress:.4,ingredients:names.slice(0,3).map(name=>({name,amount:1}))};current.queue=[{name:current.current,level:4,unit_count:1000,ingredients:current.ingredients},...Array.from({length:14},(_,i)=>({name:(i%2?'research-speed-':'physical-projectile-damage-')+(i+2),level:i+2,unit_count:1200+i*500,ingredients:names.slice(i%4,i%4+3).map(name=>({name,amount:1}))}))];
const env=(topic,data)=>({topic,tick,written_at:new Date().toISOString(),payload:{coverage:{discovery_complete:true},data}});
const topics={research:env('research',{forces:[current,{...current,force:'ally',current:'research-speed-2',level:2,progress:.9,queue:[]}]}),production:env('production',{rows:[...names.map((name,i)=>({...scope,kind:'item',quality:'normal',name,produced_per_minute:50+i*12,consumed_per_minute:70+i*10})),{...scope,surface:'vulcanus',kind:'item',quality:'normal',name:names[0],produced_per_minute:40,consumed_per_minute:30}]}),machines:env('machines',{collection_mode:'rolling',inventory_complete:true,stocks:[...names.map((name,i)=>({...scope,kind:'item',quality:'normal',name,count:1000+i*300})),{...scope,kind:'item',name:'stone-wall',quality:'normal',count:7},{...scope,kind:'item',name:'laser-turret',quality:'normal',count:5}],groups:[{...scope,type:'lab',name:'lab',status:'working',count:48},{...scope,type:'lab',name:'lab',status:'missing_science_packs',count:12},...names.map((name,i)=>({...scope,type:'assembling-machine',name:'assembling-machine-3',recipe:name,status:i%2?'working':'no_ingredients',count:14+i,products:[{type:'item',name}]}))]}),combat:env('combat',{episodes:[]})};
const researchHistory=[52800,53400,54000].map((tick,i)=>researchSample({...topics.research,tick,payload:{data:{forces:[{...current,progress:.2+i*.1}]}}}));
const flowHistory=Array.from({length:91},(_,i)=>({tick:i*600,rows:topics.production.payload.data.rows.map(r=>({...r,produced_per_minute:r.produced_per_minute*(1+Math.sin(i/7)*.1)}))}));
const researchOptions={force:'player',surface:'all',filter:'all',minutes:15},damageOptions={};let view='research';
const research=new Research(i18n,p=>{Object.assign(researchOptions,p);render();}),damage=new Damage(i18n,p=>{Object.assign(damageOptions,p);render();},()=>show('overview')),alarm=new CombatAlert(i18n,clock,id=>{damageOptions.episode=id;show('damage');});
function show(next){view=next;for(const main of document.querySelectorAll('main'))main.hidden=main.id!==(next==='sessions'?'session-screen':next+'-screen');document.querySelector('.console').dataset.view=next;for(const b of document.querySelectorAll('.screen-nav button')){b.disabled=false;if(b.id==='nav-'+next)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}render();}
function render(){for(const t of Object.values(topics))t.written_at=new Date().toISOString();const snapshot={status:{topics}};if(view==='research'){window.fixtureResearch=researchModel(topics,researchOptions,researchHistory,flowHistory);research.render(window.fixtureResearch,snapshot,()=>1);}if(view==='damage'){window.fixtureDamage=damageModel(topics,damageOptions);damage.render(window.fixtureDamage,snapshot,()=>1);}alarm.accept(combatStatus(topics,'fixture'));}
for(const key of ['overview','energy','production','logistics','research','sessions'])document.querySelector('#nav-'+key).addEventListener('click',()=>show(key));
window.fixtureStartAttack=(id='1')=>{topics.combat.payload.data.episodes=[{id,force:'player',surface:'nauvis',active:true,started_tick:54000,last_hostile_tick:54000,destroyed:16,rebuilt:4,tracking_complete:true,details_available:true,losses:[{name:'stone-wall',quality:'normal',count:12,rebuilt:3,pending:9,placement:[{name:'stone-wall',quality:'normal',count:1}],examples:[{x:420,y:172}]},{name:'laser-turret',quality:'normal',count:4,rebuilt:1,pending:3,placement:[{name:'laser-turret',quality:'normal',count:1}],examples:[{x:416,y:180}]}]}];render();};
window.fixtureRebuilt=()=>{const e=topics.combat.payload.data.episodes[0];e.losses[0].rebuilt=5;e.rebuilt=6;render();};window.fixtureEndAttack=()=>{topics.combat.payload.data.episodes[0].active=false;render();};window.fixtureRepeatHit=render;
show('research');const profile=await(await fetch('./vfx/crt-profile.json')).json();const effect=await PixiCrtOverlay.create(document.querySelector('.console'),profile,clock);effect.setEnabled(true);effect.nextGlitch=performance.now()+3600000;window.fixtureReady=true;
